import re
import subprocess
import sys

RUN = re.compile(r"(?m)^Run: https://github\.com/chidionyema/idp/actions/runs/[0-9]+\s*$")
HEAD = re.compile(r"(?m)^Greenlane-Head: ([0-9a-f]{40})\s*$")
AUTO = "agent-sandbox (auto): "

def command(argv):
    try:
        proc = subprocess.run(argv, capture_output=True, text=True, timeout=35, check=False)
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise RuntimeError(str(exc)) from exc
    if proc.returncode:
        raise RuntimeError((proc.stderr or proc.stdout or str(proc.returncode)).strip()[:180])
    return proc.stdout.strip()

def source_message(sha):
    try:
        return command(["git", "show", "-s", "--format=%B", sha])
    except RuntimeError:
        return command(["gh", "api", "repos/chidionyema/idp/commits/" + sha, "--jq", ".commit.message"])

try:
    if command(["git", "rev-parse", "--is-shallow-repository"]) != "false":
        raise RuntimeError("history is shallow")
    records = command(["git", "log", "--format=%B%x00", "HEAD"]).split("\x00")
    count = 0
    seen = set()
    for landing in records:
        lines = landing.strip().splitlines()
        if not lines or not lines[0].startswith(AUTO):
            continue
        marker = HEAD.search(landing)
        if marker is None:
            continue
        sha = marker.group(1)
        if sha in seen:
            continue
        source = source_message(sha)
        src_lines = source.strip().splitlines()
        if not src_lines or not src_lines[0].startswith(AUTO):
            continue
        if not RUN.search(source) or not re.search(r"(?m)^Agent: auto\s*$", source):
            continue
        seen.add(sha)
        count += 1
except (OSError, RuntimeError, subprocess.SubprocessError) as exc:
    sys.exit("BLIND: cannot join trusted main landing to source run: " + str(exc))
print("optimus.legion.missions_landed=" + str(count))

